public final class Vertex {
    private final int index;

    public Vertex(int index) {
        if (index < 0) {
            throw new IllegalArgumentException("Vertex index must be non-negative.");
        }
        this.index = index;
    }

    public int index() {
        return index;
    }

    @Override
    public boolean equals(Object other) {
        if (this == other) {
            return true;
        }
        if (!(other instanceof Vertex)) {
            return false;
        }

        Vertex vertex = (Vertex) other;
        return index == vertex.index;
    }

    @Override
    public int hashCode() {
        return Integer.hashCode(index);
    }

    @Override
    public String toString() {
        return "Vertex[" + index + "]";
    }
}

public final class AugmentingPath {
    private final Vertex source;
    private final Vertex sink;
    private final int bottleneck;
    private final int[] parents;

    public AugmentingPath(Vertex source, Vertex sink, int bottleneck, int[] parents) {
        this.source = source;
        this.sink = sink;
        this.bottleneck = bottleneck;
        this.parents = parents.clone();
    }

    public Vertex source() {
        return source;
    }

    public Vertex sink() {
        return sink;
    }

    public int bottleneck() {
        return bottleneck;
    }

    public Vertex parentOf(Vertex vertex) {
        return new Vertex(parents[vertex.index()]);
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Optional;
import java.util.Queue;

public final class BreadthFirstAugmentingPathFinder implements AugmentingPathFinder {
    @Override
    public Optional<AugmentingPath> find(ResidualNetwork network, FlowProblem problem) {
        boolean[] visited = new boolean[network.size()];
        int[] parents = new int[network.size()];
        Queue<Integer> queue = new ArrayDeque<>();

        Arrays.fill(parents, -1);
        queue.add(problem.source().index());
        visited[problem.source().index()] = true;

        while (!queue.isEmpty()) {
            int current = queue.poll();

            for (int next = 0; next < network.size(); next++) {
                Vertex currentVertex = new Vertex(current);
                Vertex nextVertex = new Vertex(next);
                if (visited[next] || !network.hasCapacity(currentVertex, nextVertex)) {
                    continue;
                }

                parents[next] = current;
                if (next == problem.sink().index()) {
                    return Optional.of(createPath(network, problem, parents));
                }

                visited[next] = true;
                queue.add(next);
            }
        }

        return Optional.empty();
    }

    private AugmentingPath createPath(ResidualNetwork network, FlowProblem problem, int[] parents) {
        int bottleneck = Integer.MAX_VALUE;

        for (Vertex vertex = problem.sink(); vertex.index() != problem.source().index(); vertex = new Vertex(parents[vertex.index()])) {
            Vertex previous = new Vertex(parents[vertex.index()]);
            bottleneck = Math.min(bottleneck, network.capacity(previous, vertex));
        }

        return new AugmentingPath(problem.source(), problem.sink(), bottleneck, parents);
    }
}

public final class ResidualNetwork {
    private final int[][] capacities;

    public ResidualNetwork(FlowNetwork network) {
        capacities = network.copyCapacities();
    }

    public int size() {
        return capacities.length;
    }

    public boolean hasCapacity(Vertex from, Vertex to) {
        return capacity(from, to) > 0;
    }

    public int capacity(Vertex from, Vertex to) {
        return capacities[from.index()][to.index()];
    }

    public void augment(AugmentingPath path) {
        for (Vertex vertex = path.sink(); vertex.index() != path.source().index(); vertex = path.parentOf(vertex)) {
            Vertex previous = path.parentOf(vertex);
            capacities[previous.index()][vertex.index()] -= path.bottleneck();
            capacities[vertex.index()][previous.index()] += path.bottleneck();
        }
    }

    public int[][] snapshot() {
        return IntMatrix.copyOf(capacities);
    }
}

public final class FlowNetwork {
    private final int[][] capacities;

    public FlowNetwork(int[][] capacities) {
        validate(capacities);
        this.capacities = IntMatrix.copyOf(capacities);
    }

    public int size() {
        return capacities.length;
    }

    public boolean contains(Vertex vertex) {
        return vertex != null && vertex.index() < capacities.length;
    }

    public int capacity(Vertex from, Vertex to) {
        validateVertex(from);
        validateVertex(to);
        return capacities[from.index()][to.index()];
    }

    public int[][] copyCapacities() {
        return IntMatrix.copyOf(capacities);
    }

    private void validateVertex(Vertex vertex) {
        if (!contains(vertex)) {
            throw new IllegalArgumentException("Vertex must belong to the network.");
        }
    }

    private static void validate(int[][] capacities) {
        if (capacities == null || capacities.length == 0) {
            throw new IllegalArgumentException("Graph must not be empty.");
        }

        int size = capacities.length;
        for (int row = 0; row < size; row++) {
            if (capacities[row] == null || capacities[row].length != size) {
                throw new IllegalArgumentException("Graph must be a square adjacency matrix.");
            }
            for (int column = 0; column < size; column++) {
                if (capacities[row][column] < 0) {
                    throw new IllegalArgumentException("Capacities must be non-negative.");
                }
            }
        }
    }
}

